      if character~=nil then containers[1]=character end
      if backpack~=nil then containers[#containers+1]=backpack end
      environment.chbp=containers
      for key,container in environment.pairs(environment.chbp) do
        if not key then break end
        if container:FindFirstChild(itemName) then
