            return item.Name
          elseif category=="Sword" and item.ToolTip=="Sword" then
            return item.Name
          elseif category=="Gun" and item.ToolTip=="Gun" then
            return item.Name
          elseif category=="Fruit" and item.ToolTip=="Blox Fruit" then
            return item.Name
          end
        end
      end
